import { describe,it,expect } from 'vitest';
import { analyze, RULES, WEIGHTS, commentary, PROFILES, tier } from '../src/shared/engine';
import { exampleInspection } from '../src/shared/example';
import { evidenceUrl, parseRepository } from '../src/shared/url';
describe('URL validation',()=>{
 it.each(['https://github.com/owner/repo','https://github.com/Owner/repo.git/'])('normalizes %s',url=>expect(parseRepository(url).fullName).toMatch(/^[Oo]wner\/repo$/));
 it.each(['http://github.com/a/b','https://github.com.evil.test/a/b','https://api.github.com/repos/a/b','https://github.com/a/b/tree/main','https://github.com/a/b?x=1','https://github.com/a/b#x','https://user:secret@github.com/a/b','https://github.com/a/%2e%2e','https://github.com/a/..','https://github.com/a\\b/c','https://github.com:444/a/b','https://github.com/topics/typescript','not a url','https://github.com/a/b%0a'])('rejects unsafe URL %s',url=>expect(()=>parseRepository(url)).toThrow());
 it('pins and encodes evidence',()=>expect(evidenceUrl('o/r','a'.repeat(40),'src/a b.ts',4)).toBe('https://github.com/o/r/blob/'+ 'a'.repeat(40)+'/src/a%20b.ts#L4'));
});
describe('deterministic scoring',()=>{
 it('weights and definitions total 1000',()=>{expect(RULES).toHaveLength(24);expect(new Set(RULES.map(x=>x.id)).size).toBe(24);expect(Object.values(WEIGHTS).reduce((s,n)=>s+n,0)).toBe(1000);for(const [category,max] of Object.entries(WEIGHTS))expect(RULES.filter(r=>r.category===category).reduce((s,r)=>s+r.max,0)).toBe(max);});
 it('is deterministic and ignores popularity',()=>{const i=exampleInspection();const a=analyze(i,undefined,'fixed');const b=analyze({...i,metadata:{...i.metadata,...{stars:999999}}},undefined,'fixed');expect(a.score).toEqual(b.score);expect(a.checks).toEqual(b.checks);expect(a.score).toBeGreaterThan(0);expect(a.coverage).toBe(1);});
 it('gives workflow partial credit and consistent gains',()=>{const i=exampleInspection();i.tree.push({path:'.github/workflows/other.yml',type:'blob',sha:'b'.repeat(40),mode:'100644'});i.files['.github/workflows/other.yml']='name: Other\njobs: {}';const r=analyze(i);const check=r.checks.find(c=>c.rule.id==='TST03')!;expect(check.state).toBe('partial');expect(check.ratio).toBe(.5);const improvement=r.improvements.find(c=>c.ruleId==='TST03')!;expect(improvement.potentialGain).toBe(check.maximum!-check.awarded!);});
 it('does not interpret unreadable files as missing',()=>{const i=exampleInspection();delete i.files['README.md'];i.unavailable=['README.md'];const r=analyze(i);expect(r.checks.filter(c=>c.rule.id.startsWith('DOC')).every(c=>c.state==='unknown')).toBe(true);expect(r.score).toBeNull();expect(r.coverage).toBeLessThan(.8);expect(r.improvements.some(x=>x.ruleId.startsWith('DOC'))).toBe(false);});
 it('does not claim absence in a truncated tree',()=>{const i=exampleInspection();i.treeComplete=false;i.truncated=true;const r=analyze(i);expect(r.checks.find(c=>c.rule.id==='SEC01')!.state).toBe('unknown');expect(r.improvements.some(c=>c.ruleId==='SEC01')).toBe(false);expect(r.coverage).toBeLessThan(1);});
 it.each(PROFILES)('normalizes profile %s to exactly 1000 with integer gains',profile=>{const r=analyze(exampleInspection(),profile);expect(r.checks.reduce((s,c)=>s+(c.maximum||0),0)).toBe(1000);expect(r.score).toBe(r.checks.reduce((s,c)=>s+(c.awarded||0),0));for(const i of r.improvements){expect(i.potentialGain).toBe(i.maximum-i.current);expect(Number.isInteger(i.potentialGain)).toBe(true);}expect(r.improvements.reduce((s,c)=>s+c.potentialGain,0)).toBe(1000-r.score!);});
 it('excludes documentation code checks and reallocates categories',()=>{const r=analyze(exampleInspection(),'documentation');expect(r.categories.find(c=>c.name==='Testing and CI')!.maximum).toBe(0);expect(r.checks.find(c=>c.rule.id==='TST01')!.state).toBe('not-applicable');expect(r.categories.find(c=>c.name==='Documentation')!.maximum).toBeGreaterThan(200);});
 it('changes applicability with profile corrections',()=>{const i=exampleInspection();const app=analyze(i,'application'),lib=analyze(i,'library');expect(app.checks.find(c=>c.rule.id==='MNT03')!.state).toBe('pass');expect(lib.checks.find(c=>c.rule.id==='MNT03')!.state).toBe('not-applicable');expect(app.id).not.toBe(lib.id);});
 it('withholds a score when all evidence is unknown',()=>{const i=exampleInspection();i.tree=[];i.files={};i.treeComplete=false;const r=analyze(i);expect(r.score).toBeNull();expect(r.tier).toBe('Insufficient evidence');expect(r.improvements).toEqual([]);});
 it('merges overlapping license recommendations without duplicate gains',()=>{const i=exampleInspection();i.tree=i.tree.filter(e=>e.path!=='LICENSE');i.metadata.license=null;const r=analyze(i);const merged=r.improvements.find(x=>x.ruleId==='STR01+MET02')!;expect(merged).toBeDefined();expect(r.improvements.some(x=>x.ruleId==='MET02')).toBe(false);expect(merged.potentialGain).toBe(r.checks.filter(c=>['STR01','MET02'].includes(c.rule.id)).reduce((s,c)=>s+c.maximum!-c.awarded!,0));});
 it('has evidence for every finding and exact commit links',()=>{const r=analyze(exampleInspection());for(const f of r.findings){expect(f.evidence.length).toBeGreaterThan(0);for(const e of f.evidence)expect(e.url).toContain(r.sha);}expect(r.inspection.inspected).toContain('README.md');});
 it('commentary is deterministic and never changes score or gains',()=>{const r=analyze(exampleInspection()),before=JSON.stringify(r);for(const f of r.findings){expect(commentary(r,f.ruleId,'roast')).toBe(commentary(r,f.ruleId,'roast'));expect(commentary(r,f.ruleId,'serious')).toBeTruthy();}expect(JSON.stringify(r)).toBe(before);});
 it.each([[0,'Digital Crime Scene'],[199,'Digital Crime Scene'],[200,'Spaghetti Factory'],[400,'Held Together by Hope'],[600,'Certified Spaghetti'],[750,'Actually Pretty Solid'],[900,'Suspiciously Competent'],[1000,'Suspiciously Competent']])('maps tier %s',(n,name)=>expect(tier(n as number)).toBe(name));
});

