import { describe,it,expect } from 'vitest';
import { analyze,RULES,PROFILES } from '../src/shared/engine';
import { exampleInspection } from '../src/shared/example';
import { sanitizeReport } from '../worker/redact';
import { readFileSync } from 'node:fs';
function withFiles(files:Record<string,string>){const i=exampleInspection();i.files={...files};i.tree=Object.keys(files).map((path,n)=>({path,type:'blob',mode:'100644',sha:String(n).padStart(40,'0'),size:files[path].length}));return i;}
describe('rule registry and fairness',()=>{
 const full={'README.md':'# Tool\nInstallation\nUsage\nLimitations\nTesting','package.json':'{"scripts":{"start":"node src/index.js"}}','LICENSE':'MIT','.gitignore':'.env\nnode_modules/','src/index.js':'// example','tests/tool.test.js':'// example','.github/workflows/check.yml':'permissions: read-all\nsteps:\n  - run: npm test','.github/dependabot.yml':'version: 2','SECURITY.md':'Use private reporting.','eslint.config.js':'export default []','.prettierrc':'{}','package-lock.json':'{}','CHANGELOG.md':'Initial release.','CONTRIBUTING.md':'Contributing guide.','.github/ISSUE_TEMPLATE/bug.md':'Bug report.','CODE_OF_CONDUCT.md':'Participation expectations.'};
 it.each(RULES)('$id has a tested positive recognition case',rule=>{const r=analyze(withFiles(full),'application');expect(r.checks.find(c=>c.rule.id===rule.id)!.state).toBe('pass');});
 it('all recognized practices total exactly 1000',()=>expect(analyze(withFiles(full),'application').score).toBe(1000));
 it('a minimal repository is not awarded imaginary practices',()=>{const i=withFiles({'entry.js':'// example','package.json':'{}'});i.metadata.description='';i.metadata.license=null;const r=analyze(i,'application');expect(r.coverage).toBe(1);expect(r.score).toBe(0);expect(r.improvements.reduce((s,x)=>s+x.potentialGain,0)).toBe(1000);});
 it('does not reward vendor tests or dependency READMEs',()=>{const i=withFiles({'vendor/tests/example.test.js':'// test','node_modules/pkg/README.md':'installation usage limitations'});const r=analyze(i,'general');expect(r.checks.find(c=>c.rule.id==='TST01')!.state).toBe('fail');expect(r.checks.find(c=>c.rule.id==='DOC01')!.state).toBe('fail');});
 it('requires weighted 80% coverage including unknown README evidence',()=>{const i=withFiles(full);delete i.files['README.md'];const r=analyze(i,'application');expect(r.coverage).toBe(.77);expect(r.score).toBeNull();});
 it.each(PROFILES)('withholds a result for unknown evidence under profile %s',profile=>{const i=withFiles({});i.treeComplete=false;const r=analyze(i,profile);expect(r.score).toBeNull();expect(r.improvements).toHaveLength(0);});
 it('keeps a known subset conditional and unknowns without numerical awards',()=>{const i=withFiles(full);delete i.files['.github/workflows/check.yml'];const r=analyze(i,'application');expect(r.coverage).toBe(.91);expect(r.score).toBe(1000);expect(r.checks.find(c=>c.rule.id==='TST03')!.awarded).toBeNull();expect(r.categories.reduce((s,c)=>s+c.maximum,0)).toBe(1000);});
 it('uses real documentation-only evidence without test penalties',()=>{const r=analyze(withFiles({'README.md':'# Documentation\n## Navigation\n## Scope','docs/guide.md':'Guide','LICENSE':'MIT'}));expect(r.detectedProfile).toBe('documentation');expect(r.checks.find(c=>c.rule.id==='TST01')!.state).toBe('not-applicable');expect(r.score).not.toBeNull();});
 it.each([['rust',{'Cargo.toml':'[package]','src/main.rs':'fn main() {}','tests/smoke.rs':'// example','Cargo.lock':'# generated'}],['go',{'go.mod':'module demo','cmd/main.go':'package main','cmd/main_test.go':'// example','go.sum':'sum'}],['python',{'pyproject.toml':'[project]','src/tool.py':'# example','tests/test_tool.py':'# example','uv.lock':'# generated'}]])('recognizes %s package paths without reading dependency code',(_,files)=>{const r=analyze(withFiles(files as Record<string,string>),'general');expect(r.checks.find(c=>c.rule.id==='MNT03')!.state).toBe('pass');expect(r.checks.find(c=>c.rule.id==='TST01')!.state).toBe('pass');});
 it('documents every rule and version',()=>{const doc=readFileSync('SCORING.md','utf8');for(const rule of RULES){expect(doc).toContain('### '+rule.id+' — '+rule.title);expect(doc).toContain('Base maximum: '+rule.max);}});
 it('redacts path credentials without fabricating blob references',()=>{const secret='ghp_'+'x'.repeat(36);const i=withFiles({['tests/'+secret+'.test.js']:'// example'});const report=analyze(i,'general'),safe=sanitizeReport(report);expect(JSON.stringify(safe)).not.toContain(secret);const evidence=safe.checks.find(c=>c.rule.id==='TST01')!.evidence[0];expect(evidence.path).toBeNull();expect(evidence.url).toBe('https://github.com/'+i.metadata.fullName+'/tree/'+i.sha);expect(evidence.confidence).toBe('low');});
 it('recognizes CLI and library profile evidence',()=>{expect(analyze(withFiles({'package.json':'{"bin":{"demo":"cli.js"}}'})).detectedProfile).toBe('cli');expect(analyze(withFiles({'package.json':'{"exports":"./src/main.js"}'})).detectedProfile).toBe('library');});
});

it('does not penalize alternative CI for GitHub-specific configuration',()=>{const r=analyze(withFiles({'.gitlab-ci.yml':'test: script: npm test','src/main.js':'// example'}),'application');expect(r.checks.find(c=>c.rule.id==='TST02')!.state).toBe('pass');for(const id of ['TST03','SEC04']){expect(r.checks.find(c=>c.rule.id===id)!.state).toBe('not-applicable');expect(r.improvements.some(x=>x.ruleId===id)).toBe(false);}});

